DROP VIEW IF EXISTS M_HIGH;
DROP TABLE IF EXISTS M_SQL_RESULT;
DROP TABLE IF EXISTS M_SQL_COURSE;
DROP TABLE IF EXISTS M_SQL_STUDENT;
CREATE TABLE M_SQL_STUDENT (
 SID TEXT PRIMARY KEY NOT NULL,
 Name TEXT NOT NULL,
 Class TEXT NOT NULL
);
CREATE TABLE M_SQL_COURSE (
 CID TEXT PRIMARY KEY NOT NULL,
 Title TEXT NOT NULL
);
CREATE TABLE M_SQL_RESULT (
 SID TEXT NOT NULL REFERENCES M_SQL_STUDENT(SID),
 CID TEXT NOT NULL REFERENCES M_SQL_COURSE(CID),
 Mark INTEGER CHECK (Mark BETWEEN 0 AND 100),
 PRIMARY KEY (SID, CID)
);
