 ('S3','C1',90),('S3','C3',NULL);

SELECT Name AS StudentName, Class
FROM M_SQL_STUDENT
ORDER BY Class DESC, SID ASC;

SELECT SID, Mark, Mark * 0.9 AS Adjusted
FROM M_SQL_RESULT
ORDER BY SID, CID;
SELECT UPPER(SUBSTR(TRIM(' s1 '),1,1)) || '-01' AS Code;

SELECT SID, CID, Mark FROM M_SQL_RESULT
WHERE Mark > (SELECT AVG(Mark) FROM M_SQL_RESULT)
ORDER BY SID, CID;
SELECT SID, Name FROM M_SQL_STUDENT
WHERE SID IN (SELECT SID FROM M_SQL_RESULT WHERE CID = 'C1')
ORDER BY SID;

SELECT * FROM M_SQL_RESULT WHERE SID='S2' AND CID='C1';
